type LookupRow = { id: string; name: string; createdBy: string; modifiedBy: string; modifiedAt: string; active?: boolean };
type OfficeLocation = { id: string; name: string; address1: string; address2: string; city: string; state: string; country: string; zipCode: string; createdAt: string; modifiedAt: string };
type BillingContact = { id: string; firstName: string; lastName: string; email: string; mobile: string; address: string; country: string; state: string; city: string; zipCode: string; active: boolean };
type EmailTemplate = { id: string; name: string; module: string; subject: string; description: string; active: boolean; body: string; replyTo?: string; cc?: string; bcc?: string; attachments?: string[] };
type OrgSettings = { [key: string]: string | boolean | string[] };

